import java.util.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][] cache;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        cache = new HashMap[2][n + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= n; j++) {
                cache[i][j] = new HashMap<>();
            }
        }

        int result = solve(n, 0, true) % mod;
        System.out.println(result);
        sc.close();
    }

    static int invnum(int[] sequence) {
        int count = 0;
        for (int i = 0; i < sequence.length; i++) {
            for (int j = i + 1; j < sequence.length; j++) {
                if (sequence[i] > sequence[j]) {
                    count++;
                }
            }
        }
        return count;
    }

    static int naive(int N, int k, boolean flag) {
        List<int[]> permutations = generatePermutations(N);
        int count = 0;
        for (int[] p : permutations) {
            for (int[] q : permutations) {
                if ((comparePermutations(p, q) < 0 || !flag) && (invnum(p) - invnum(q) > k)) {
                    count++;
                }
            }
        }
        return count;
    }

    static List<int[]> generatePermutations(int N) {
        List<int[]> result = new ArrayList<>();
        permute(new int[N], new boolean[N], 0, result);
        return result;
    }

    static void permute(int[] arr, boolean[] used, int depth, List<int[]> result) {
        if (depth == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = 0; i < arr.length; i++) {
            if (!used[i]) {
                used[i] = true;
                arr[depth] = i;
                permute(arr, used, depth + 1, result);
                used[i] = false;
            }
        }
    }

    static int comparePermutations(int[] p, int[] q) {
        for (int i = 0; i < p.length; i++) {
            if (p[i] != q[i]) {
                return p[i] - q[i];
            }
        }
        return 0;
    }

    static int solve(int N, int K, boolean flag) {
        if (cache[flag ? 1 : 0][N].containsKey(K)) {
            return cache[flag ? 1 : 0][N].get(K);
        }
        int res;
        if (N == 1) {
            res = (!flag) ? (K < 0 ? 1 : 0) : 0;
            cache[flag ? 1 : 0][N].put(K, res);
            return res;
        }
        int max_inv = (N * (N - 1)) / 2;
        if (K < -max_inv - 1) {
            res = solve(N, -max_inv - 1, flag);
            cache[flag ? 1 : 0][N].put(K, res);
            return res;
        }
        if (K >= max_inv) {
            cache[flag ? 1 : 0][N].put(K, 0);
            return 0;
        }
        long total = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) continue;
            int weight = Math.min(N - delta, delta + N);
            int newFlag = (delta == 0) ? 1 : 0;
            total += (long) solve(N - 1, K - delta, delta == 0) * weight;
            total %= mod;
        }
        res = (int) total;
        cache[flag ? 1 : 0][N].put(K, res);
        return res;
    }
}
